#include <stdio.h>
#include <stdlib.h>

int binarySearch(int arr[], int n, int x) {
    int left = 0;
    int right = n - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (arr[mid] == x) {
            return mid;
        } else if (arr[mid] < x) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return -1;
}

int main() {
    int n, x;

    // Read the number of elements in the array
    scanf("%d", &n);

    // Allocate memory for the array
    int *arr = (int *)malloc(n * sizeof(int));

    // Read the sorted array from stdin
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Read the target value x
    scanf("%d", &x);

    // Perform binary search and print the result
    int index = binarySearch(arr, n, x);
    printf("%d\n", index);

    // Free allocated memory
    free(arr);

    return 0;
}
